import React, { useEffect, useState } from "react";

export default function UserHistory({ onCancel }) {
  const [depositHistory, setDepositHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 20;
  const token = localStorage.getItem("authToken");

  useEffect(() => {
    fetchDepositHistory();
  }, []);

  const fetchDepositHistory = async () => {
    setLoading(true);
    setMessage("");

    try {
      const res = await fetch("http://localhost:8080/api/deposit/my-history", {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      if (!res.ok) {
        throw new Error("Failed to load deposit history");
      }

      const data = await res.json();

      const formatStatus = (status) =>
        status === "APPROVED" ? "COMPLETED" : status;

      const formattedDeposits = data.map((item) => ({
        id: item.id,
        mobile: item.mobile,
        gameId: item.gameId,
        amount: item.amount,
        method: item.method,
        transactionId: item.transactionId,
        number: item.senderNumber,
        status: formatStatus(item.status),
        date: item.requestedAt,
      }));

      setDepositHistory(
        formattedDeposits.sort((a, b) => new Date(b.date) - new Date(a.date))
      );
    } catch (err) {
      console.error(err);
      setMessage("Failed to load deposit history.");
    } finally {
      setLoading(false);
    }
  };

  const statusColor = {
    PENDING: "bg-yellow-500",
    REJECTED: "bg-red-600",
    COMPLETED: "bg-green-600",
  };

  const totalItems = depositHistory.length;
  const totalPages = Math.ceil(totalItems / itemsPerPage);
  const paginatedData = depositHistory.slice(
    (currentPage - 1) * itemsPerPage,
    currentPage * itemsPerPage
  );

  return (
    <div className="max-w-7xl mx-auto p-6">
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white">
          💰 My Deposit History
        </h2>
        <button
          onClick={onCancel}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-md"
        >
          ← Back
        </button>
      </div>

      {loading ? (
        <p className="text-center text-gray-500">Loading...</p>
      ) : message ? (
        <p className="text-center text-red-600 font-semibold">{message}</p>
      ) : depositHistory.length === 0 ? (
        <p className="text-center text-gray-500">No deposit history found.</p>
      ) : (
        <>
          <div className="overflow-x-auto bg-white dark:bg-gray-900 border rounded-xl shadow mb-6">
            <table className="min-w-full text-sm text-left divide-y divide-gray-200 dark:divide-gray-700">
              <thead className="bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-200 text-xs font-semibold">
                <tr>
                  <th className="px-4 py-3">#</th>
                  <th className="px-4 py-3">Txn ID</th>
                  <th className="px-4 py-3">Mobile</th>
                  <th className="px-4 py-3">Game ID</th>
                  <th className="px-4 py-3">Method</th>
                  <th className="px-4 py-3">Number</th>
                  <th className="px-4 py-3">Amount</th>
                  <th className="px-4 py-3">Status</th>
                  <th className="px-4 py-3">Date</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-800 text-gray-800 dark:text-gray-100">
                {paginatedData.map((item, index) => (
                  <tr
                    key={item.id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-800"
                  >
                    <td className="px-4 py-2">
                      {totalItems - ((currentPage - 1) * itemsPerPage + index)}
                    </td>
                    <td className="px-4 py-2">{item.transactionId}</td>
                    <td className="px-4 py-2">{item.mobile}</td>
                    <td className="px-4 py-2">{item.gameId}</td>
                    <td className="px-4 py-2">{item.method}</td>
                    <td className="px-4 py-2">{item.number}</td>
                    <td className="px-4 py-2 font-semibold text-gray-900 dark:text-white">
                      ৳ {Number(item.amount).toFixed(2)}
                    </td>
                    <td className="px-4 py-2">
                      <span
                        className={`px-2 py-1 text-xs font-semibold text-white rounded ${
                          statusColor[item.status] || "bg-gray-500"
                        }`}
                      >
                        {item.status}
                      </span>
                    </td>
                    <td className="px-4 py-2">
                      {new Date(item.date).toLocaleString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Pagination Controls */}
          <div className="flex justify-center items-center gap-4">
            <button
              onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))}
              disabled={currentPage === 1}
              className="px-4 py-2 bg-gray-300 text-sm font-semibold rounded hover:bg-gray-400 disabled:opacity-50"
            >
              ← Previous
            </button>
            <span className="text-gray-700 font-medium">
              Page {currentPage} of {totalPages}
            </span>
            <button
              onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))}
              disabled={currentPage === totalPages}
              className="px-4 py-2 bg-gray-300 text-sm font-semibold rounded hover:bg-gray-400 disabled:opacity-50"
            >
              Next →
            </button>
          </div>
        </>
      )}
    </div>
  );
}
